<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('leads.view');
$pageTitle='Campañas de leads';$rows=db()->query("SELECT lc.*,u.name creator_name,(SELECT COUNT(*) FROM lead_forms lf WHERE lf.campaign_id=lc.id) forms,(SELECT COUNT(*) FROM lead_submissions ls JOIN lead_forms lf2 ON lf2.id=ls.form_id WHERE lf2.campaign_id=lc.id) leads FROM lead_campaigns lc LEFT JOIN users u ON u.id=lc.created_by ORDER BY lc.created_at DESC")->fetchAll();require __DIR__.'/includes/header.php';
?>
<section class="panel"><div class="panel-header"><div><h2>Generación de leads</h2><span class="table-sub">Organiza campañas, formularios y resultados de captación.</span></div><?php if(has_permission('leads.manage')):?><a class="btn btn-primary" href="lead_campaign_form.php">+ CREAR CAMPAÑA</a><?php endif;?></div><div class="table-wrap"><?php if(!$rows):?><div class="empty">Aún no hay campañas.</div><?php else:?><table class="data-table"><thead><tr><th>Campaña</th><th>Canal</th><th>Periodo</th><th>Presupuesto</th><th>Formularios</th><th>Leads</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><strong><?=e($r['name'])?></strong><span class="table-sub"><?=e($r['objective']?:'Sin objetivo definido')?></span></td><td><?=e(ucfirst($r['channel']))?></td><td><?=e(format_date($r['start_date']))?> – <?=e(format_date($r['end_date']))?></td><td><?=e(format_money($r['budget'],$r['currency']))?></td><td><?=(int)$r['forms']?></td><td><strong><?=(int)$r['leads']?></strong></td><td><span class="badge badge-<?=e($r['status']==='active'?'green':($r['status']==='completed'?'blue':'orange'))?>"><?=e($r['status'])?></span></td><td><?php if(has_permission('leads.manage')):?><a class="btn btn-light btn-small" href="lead_campaign_form.php?id=<?=(int)$r['id']?>">Editar</a><?php endif;?></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></section>
<?php require __DIR__.'/includes/footer.php';?>
